Here's a Swift implementation of the Tennis Score Tracker app based on the outlined design:

```swift
import UIKit

// MARK: - Models

struct Player {
    let name: String
}

enum PointType: String, CaseIterable {
    case winner, unforcedError, forcedError, ace, returnWinner, serveWinner
    var description: String { return self.rawValue.capitalized }
}

struct Point {
    let player: Player
    let type: PointType?
}

class Game {
    private(set) var points = [Point]()
    private(set) var playerAPoints = 0
    private(set) var playerBPoints = 0
    private(set) var winner: Player?
    private let playerA: Player
    private let playerB: Player

    init(playerA: Player, playerB: Player) {
        self.playerA = playerA
        self.playerB = playerB
    }

    func addPoint(for player: Player, type: PointType?) {
        let newPoint = Point(player: player, type: type)
        points.append(newPoint)

        if player == playerA {
            playerAPoints += 1
        } else {
            playerBPoints += 1
        }

        checkIfOver()
    }

    private func checkIfOver() {
        let a = playerAPoints
        let b = playerBPoints

        if a >= 4 && (a - b) >= 2 {
            winner = playerA
        } else if b >= 4 && (b - a) >= 2 {
            winner = playerB
        }
    }

    var currentScore: (String, String) {
        let aStr = pointsToLabel(points: playerAPoints,
                                otherPoints: playerBPoints,
                                forPlayer: playerA)
        let bStr = pointsToLabel(points: playerBPoints,
                                otherPoints: playerAPoints,
                                forPlayer: playerB)

        return (aStr, bStr)
    }

    private func pointsToLabel(points: Int, otherPoints: Int, forPlayer player: Player) -> String {
        if let winner = winner {
            return winner == player ? "Win" : "Lose"
        }

        switch points {
        case 0: return "Love"
        case 1: return "15"
        case 2: return "30"
        case 3: return "40"
        default:
            if points == otherPoints {
                return "Deuce"
            } else {
                return "Adv"
            }
        }
    }
}

class Set {
    private(set) var games = [Game]()
    private(set) var winner: Player?
    private let playerA: Player
    private let playerB: Player

    init(playerA: Player, playerB: Player) {
        self.playerA = playerA
        self.playerB = playerB
    }

    var currentGame: Game? { return games.last }

    var playerAGames: Int {
        return games.filter { $0.winner == playerA }.count
    }

    var playerBGames: Int {
        return games.filter { $0.winner == playerB }.count
    }

    func addGame(_ game: Game) {
        games.append(game)
        checkIfOver()
    }

    private func checkIfOver() {
        if playerAGames >= 6 && playerAGames - playerBGames >= 2 {
            winner = playerA
        } else if playerBGames >= 6 && playerBGames - playerAGames >= 2 {
            winner = playerB
        }
    }
}

class Match {
    let players: [Player]
    private(set) var sets = [Set]()
    private(set) var currentSetIndex = 0
    private(set) var isAdvancedMode = false

    private(set) var playerAGamesCount = 0
    private(set) var playerBGamesCount = 0

    init(players: [Player]) {
        self.players = players
        startNewSet()
    }

    var currentSet: Set? {
        return sets.indices.contains(currentSetIndex) ? sets[currentSetIndex] : nil
    }

    var currentGame: Game? {
        return currentSet?.currentGame
    }

    func startNewSet() {
        guard sets.count < 3 else { return }

        let newSet = Set(playerA: players[0], playerB: players[1])
        sets.append(newSet)
        currentSetIndex = sets.count - 1
    }

    func startNewGame() {
        guard let currentSet = currentSet else { return }

        let newGame = Game(playerA: players[0], playerB: players[1])
        currentSet.addGame(newGame)
    }

    func addPoint(for player: Player, type: PointType?) {
        guard let currentGame = currentGame else {
            startNewGame()
            return
        }

        currentGame.addPoint(for: player, type: type)

        if currentGame.winner != nil {
            if let currentSet = currentSet {
                if currentSet.winner != nil {
                    // Set is over, update match stats
                    if currentSet.winner == players[0] {
                        playerAGamesCount += 1
                    } else {
                        playerBGamesCount += 1
                    }

                    // Check if match is over
                    if playerAGamesCount == 2 || playerBGamesCount == 2 {
                        // Match is over
                    } else {
                        startNewSet()
                        startNewGame()
                    }
                } else {
                    startNewGame()
                }
            }
        }
    }
}

// MARK: - View Controller

class TennisViewController: UIViewController {
    @IBOutlet weak var playerASetNameLabel: UILabel!
    @IBOutlet weak var playerBSetNameLabel: UILabel!
    @IBOutlet weak var currentSetLabel: UILabel!
    @IBOutlet weak var currentGameScoreLabel: UILabel!
    @IBOutlet weak var playerAGameCountLabel: UILabel!
    @IBOutlet weak var playerBGameCountLabel: UILabel!
    @IBOutlet weak var advancedModeSwitch: UISwitch!

    private var match: Match!

    override func viewDidLoad() {
        super.viewDidLoad()

        let player1 = Player(name: "Player A")
        let player2 = Player(name: "Player B")
        match = Match(players: [player1, player2])

        updateUI()
    }

    private func updateUI() {
        guard let match = match else { return }

        playerASetNameLabel.text = "\(match.playerAGamesCount)"
        playerBSetNameLabel.text = "\(match.playerBGamesCount)"

        currentSetLabel.text = "Set \(match.currentSetIndex + 1)/\(match.sets.count)"

        guard let currentSet = match.currentSet else { return }
        playerAGameCountLabel.text = "\(currentSet.playerAGames)"
        playerBGameCountLabel.text = "\(currentSet.playerBGames)"

        if let currentGame = match.currentGame {
            let (aScore, bScore) = currentGame.currentScore
            currentGameScoreLabel.text = "\(aScore)-\(bScore)"
        } else {
            currentGameScoreLabel.text = "No game in progress"
        }
    }

    @IBAction func addPointForPlayerA(_ sender: UIButton) {
        guard let match = match else { return }

        if advancedModeSwitch.isOn {
            showPointTypeSelection(for: match.players[0])
        } else {
            match.addPoint(for: match.players[0], type: nil)
            updateUI()
        }
    }

    @IBAction func addPointForPlayerB(_ sender: UIButton) {
        guard let match = match else { return }

        if advancedModeSwitch.isOn {
            showPointTypeSelection(for: match.players[1])
        } else {
            match.addPoint(for: match.players[1], type: nil)
            updateUI()
        }
    }

    private func showPointTypeSelection(for player: Player) {
        let alert = UIAlertController(title: "Select Point Type", message: nil, preferredStyle: .actionSheet)

        for type in PointType.allCases {
            let action = UIAlertAction(title: type.description, style: .default) { [weak self] _ in
                self?.match.addPoint(for: player, type: type)
                self?.updateUI()
            }
            alert.addAction(action)
        }

        present(alert, animated: true)
    }
}
```

