<body>
  <header>
    <div><strong>Advanced Notepad</strong></div>
    <div class="controls">
      <button id="new-btn" title="New File">New</button>
      <button id="open-btn" title="Open File">Open</button>
      <button id="save-btn" title="Save File (Ctrl+S)">Save</button>
      <select id="language-select" title="Select Language">
        <option value="plaintext">Plain Text</option>
        <option value="javascript" selected>JavaScript</option>
