let marked = window.marked;
let DOMPurify = window.DOMPurify;
let Prism = window.Prism;

export const URLs = {
	marked: "https://cdn.jsdelivr.net/npm/marked/src/marked.min.js",
	DOMPurify: "https://cdn.jsdelivr.net/npm/dompurify@2.3.3/dist/purify.es.min.js",
}

// Fix indentation
function deIndent(text) {
	let indent = text.match(/^[\r\n]*([\t ]+)/);

	if (indent) {
		indent = indent[1];

		text = text.replace(RegExp("^" + indent, "gm"), "");
	}

	return text;
}

/* -------------------------
   New helper function to
   wrap text in double quotes in a red span.
-------------------------- */
function highlightQuotesInElement(el) {
	// Iterate over all child nodes
	for (let child = el.firstChild; child !== null; child = child.nextSibling) {
		// If the node is a text node…
		if (child.nodeType === Node.TEXT_NODE) {
			let text = child.textContent;
			// Check if the text contains at least one quotation mark.
			if (text.indexOf('"') !== -1) {
				const frag = document.createDocumentFragment();
				let lastIndex = 0;
				// This regex finds text enclosed in double quotes.
				const regex = /"([^"]+)"/g;
				let match;
				while ((match = regex.exec(text)) !== null) {
					// Append text before the match.
					if (match.index > lastIndex) {
						frag.appendChild(document.createTextNode(text.slice(lastIndex, match.index)));
					}
					// Create a span for the quoted text.
					let span = document.createElement('span');
					span.style.color = 'red';
					// match[0] includes the quotes.
					span.textContent = match[0];
					frag.appendChild(span);
					lastIndex = regex.lastIndex;
				}
				// Append any remaining text.
				if (lastIndex < text.length) {
					frag.appendChild(document.createTextNode(text.slice(lastIndex)));
				}
				// Replace the original text node with the new fragment.
				child.parentNode.replaceChild(frag, child);
			}
